// js
const terms = ctx.subject.employment.terms;
const rate = get(terms, 'rate', {});
const monthly =
	get(rate, 'unit', 'MONTHLY') === 'MONTHLY'
		? Number(get(rate, 'amount', 0))
		: Number(get(ctx, 'base_pay', 0));
const daily =
	(monthly * ctx.lookup.months_per_year) /
	(ctx.lookup.weeks_per_year * Number(get(terms, 'normal_days_per_week', 5)));
const hours = Number(ctx.entry.quantity);
return (
	daily *
	(hours <= Number(get(terms, 'normal_hours_per_day', 8)) / ctx.lookup.half_day_divisor
		? ctx.lookup.employer_request_days_up_to_half
		: ctx.lookup.employer_request_days_above_half)
);

